WITH filtered AS (SELECT *, TRIM(event_type) clean_event_type, COALESCE(page, 'N/A') page_filled FROM web_events WHERE event_time >= TO_DATE('2023-06-08') AND page IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_burst FROM filtered), islands AS (SELECT id, session_id, event_type, event_time, page_filled, SUM(is_new_burst) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps), gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM islands), sessions_web_events AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM gaps), scored AS (SELECT *, LAG(burst_id, 1, 0) OVER (PARTITION BY event_type ORDER BY session_id_2 ASC, id ASC) prev_burst_id, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY session_start_flag DESC, id ASC) row_seq, NTILE(3) OVER (PARTITION BY session_id ORDER BY burst_id ASC, id ASC) burst_id_bucket, SUM(session_id_2) OVER (PARTITION BY event_type ORDER BY session_id_2 ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_session_id_2, COUNT(session_id_2) OVER (PARTITION BY event_type) event_type_count_session_id_2 FROM sessions_web_events) SELECT id, session_id, event_type, session_start_flag, row_seq, burst_id_bucket, cumulative_session_id_2, CASE WHEN event_type RLIKE '^(click|search)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS event_type_zone FROM scored ORDER BY event_type DESC, burst_id_bucket DESC;
